    private void jButton4ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton4ActionPerformed
    db_conn dd=new db_conn(); 
    try{
    dd.query="insert into take(Name,Contact,Address,Book_name,author) values(?,?,?,?,?)";
    dd.a.add(n.getText());
    dd.a.add(c.getText());
    dd.a.add(a.getText());
    dd.a.add((String)au.getSelectedItem());
    dd.a.add((String)au.getSelectedItem());
    dd.update();
      
    dd=new db_conn();  
    dd.query="insert into db(Name,Contact,Address,Book_Name,author) values(?,?,?,?,?)";       
    dd.a.add(n.getText());
    dd.a.add(c.getText());
    dd.a.add(a.getText());
    dd.a.add((String)au.getSelectedItem());
    dd.a.add((String)au.getSelectedItem());
    dd.update();
    
    JOptionPane.showMessageDialog(null,"Details Sucsessfully Added","Done",JOptionPane.INFORMATION_MESSAGE);
    
    dd=new db_conn();  
    dd.query="select * from take where Name=?";
    dd.a.add(n.getText());
    ResultSet rs=dd.select();
    if(rs.next()){
       String temp= Integer.toString(rs.getInt(2));
       id.setText("Your Book ID Is:  "+temp);
    }
    }
    catch(NullPointerException e){
           JOptionPane.showMessageDialog(null,"Database Connection error");
    }
    catch(SQLException e){
           JOptionPane.showMessageDialog(null,"Database Connection error");
    }
    }//GEN-LAST:event_jButton4ActionPerformed

